import java.util.*;

class Solution {
    public double findMedianSortedArrays(int[] a, int[] b) {
        int total = a.length + b.length;
        if (total % 2 == 1) return kth(a, 0, b, 0, total / 2 + 1);
        return (kth(a, 0, b, 0, total / 2) + kth(a, 0, b, 0, total / 2 + 1)) / 2.0;
    }

    // k-th smallest (1-based) of a[i..] and b[j..]
    private int kth(int[] a, int i, int[] b, int j, int k) {
        if (i == a.length) return b[j + k - 1];
        if (j == b.length) return a[i + k - 1];
        if (k == 1) return Math.min(a[i], b[j]);
        int p = Math.min(k / 2, a.length - i);
        int q = Math.min(k / 2, b.length - j);
        if (a[i + p - 1] <= b[j + q - 1]) {
            return kth(a, i + p, b, j, k - p);   // a's first p cannot be the k-th
        } else {
            return kth(a, i, b, j + q, k - q);   // b's first q cannot be the k-th
        }
    }
}

