class Solution:
    def findMedianSortedArrays(self, a: List[int], b: List[int]) -> float:
        def kth(i, j, k):
            if i == len(a): return b[j + k - 1]
            if j == len(b): return a[i + k - 1]
            if k == 1: return min(a[i], b[j])
            h = k // 2
            ai = min(i + h, len(a)) - 1; bj = min(j + h, len(b)) - 1
            if a[ai] <= b[bj]: return kth(ai + 1, j, k - (ai - i + 1))
            return kth(i, bj + 1, k - (bj - j + 1))
        t = len(a) + len(b)
        if t % 2: return float(kth(0, 0, t // 2 + 1))
        return (kth(0, 0, t // 2) + kth(0, 0, t // 2 + 1)) / 2

