function findMedianSortedArrays(a, b) {
  const m = []; let i = 0, j = 0;
  while (i < a.length || j < b.length) { if (j >= b.length || (i < a.length && a[i] <= b[j])) m.push(a[i++]); else m.push(b[j++]); }
  const n = m.length; return n % 2 ? m[(n - 1) / 2] : (m[n / 2 - 1] + m[n / 2]) / 2;
}
